def transform(grid):
    from collections import Counter
    all_cells = [cell for row in grid for cell in row]
    color_counts = Counter(all_cells)
    if len(color_counts) <= 1:
        return grid
    bg_color = color_counts.most_common(1)[0][0]

    height = len(grid)
    width = len(grid[0])

    result = [[bg_color] * width for _ in range(height)]

    # Rule: foreground in early rows (row ≤ 1) or left edge (col = 0) → value 2
    # Other foreground → value 1
    for r in range(height):
        for c in range(width):
            if grid[r][c] != bg_color:
                if r <= 1 or c == 0:
                    result[r][c] = 2
                else:
                    result[r][c] = 1

    return result
